from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]
def get(n):return json.loads((P/'data'/n).read_text())
def write(n,s):(P/n).write_text('\n'.join(x.rstrip() for x in s.splitlines()).strip()+'\n')
def table(h,rows):return '\n'.join(['| '+' | '.join(h)+' |','|'+'|'.join(['---']*len(h))+'|']+['| '+' | '.join(str(x).replace('|','&#124;') for x in r)+' |' for r in rows])
def main():
 a=get('spec-audit.json');h=get('hvac-review.json');j=get('owner-specifications.json')
