 for x in a['items']:s+=['<a id="'+x['id'].lower()+'"></a>','## '+x['id']+' · '+x['finding'],'','**확인 한계:** '+x['previous_gap'],'','**R2 처리:** '+x['r2_action'],'','**업체에 받을 근거:** '+x['bid_evidence_required'],'']
